use std::fs

struct Bst {
    key: Vec<int>,
    l: Vec<int>,
    r: Vec<int>,
    root: int,
    found: bool,
    out: Vec<int>,
}

impl Bst {
    fn find(self, x: int) -> bool {
        let mut n = self.root
        while n >= 0 {
            let k = self.key[n as usize]
            if x == k {
                return true
            }
            if x < k {
                n = self.l[n as usize]
            } else {
                n = self.r[n as usize]
            }
        }
        false
    }

    fn insert(self, x: int) -> bool {
        if self.find(x) {
            return false
        }
        let id: int = self.key.len() as int
        self.key.push(x)
        self.l.push(-1)
        self.r.push(-1)
        if self.root < 0 {
            self.root = id
            return true
        }
        let mut n = self.root
        loop {
            if x < self.key[n as usize] {
                if self.l[n as usize] < 0 {
                    self.l[n as usize] = id
                    break
                }
                n = self.l[n as usize]
            } else {
                if self.r[n as usize] < 0 {
                    self.r[n as usize] = id
                    break
                }
                n = self.r[n as usize]
            }
        }
        true
    }

    fn del(self, node: int, x: int) -> int {
        if node < 0 {
            return -1
        }
        let k = self.key[node as usize]
        if x < k {
            let c = self.del(self.l[node as usize], x)
            self.l[node as usize] = c
            return node
        }
        if x > k {
            let c = self.del(self.r[node as usize], x)
            self.r[node as usize] = c
            return node
        }
        self.found = true
        if self.l[node as usize] < 0 {
            return self.r[node as usize]
        }
        if self.r[node as usize] < 0 {
            return self.l[node as usize]
        }
        let mut s = self.r[node as usize]
        while self.l[s as usize] >= 0 {
            s = self.l[s as usize]
        }
        let sk = self.key[s as usize]
        self.key[node as usize] = sk
        let c = self.del(self.r[node as usize], sk)
        self.r[node as usize] = c
        node
    }

    fn walk(self, n: int) {
        if n < 0 {
            return
        }
        self.walk(self.l[n as usize])
        self.out.push(self.key[n as usize])
        self.walk(self.r[n as usize])
    }

    fn height(self, n: int) -> int {
        if n < 0 {
            return 0
        }
        let a = self.height(self.l[n as usize])
        let b = self.height(self.r[n as usize])
        if a > b {
            a + 1
        } else {
            b + 1
        }
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Bst { key: [], l: [], r: [], root: -1, found: false, out: [] }
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse::<int>().unwrap_or(0)
            if t.insert(x) {
                println("ok")
            } else {
                println("dup")
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse::<int>().unwrap_or(0)
            if t.find(x) {
                println("yes")
            } else {
                println("no")
            }
        } else if cmd == "delete" {
            let x: int = parts[1].parse::<int>().unwrap_or(0)
            t.found = false
            let nr = t.del(t.root, x)
            t.root = nr
            if t.found {
                println("ok")
            } else {
                println("missing")
            }
        } else if cmd == "inorder" {
            t.out = []
            t.walk(t.root)
            if t.out.len() == 0 {
                println("<empty>")
            } else {
                let mut s = ""
                let mut first = true
                let items: Vec<int> = t.out.clone()
                for v in items {
                    if !first {
                        s = s + " "
                    }
                    first = false
                    s = s + "${v}"
                }
                println(s)
            }
        } else if cmd == "height" {
            println("${t.height(t.root)}")
        } else if cmd == "min" || cmd == "max" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut n = t.root
                if cmd == "min" {
                    while t.l[n as usize] >= 0 {
                        n = t.l[n as usize]
                    }
                } else {
                    while t.r[n as usize] >= 0 {
                        n = t.r[n as usize]
                    }
                }
                println("${t.key[n as usize]}")
            }
        }
    }
}

